import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

const MARGIN = { top: 16, right: 20, bottom: 36, left: 56 };
const POINTS = 200;
const PERIODS = 20;
const DEVIATIONS = 2;

/** A closing price per date; the mean and the bands are computed from it. */
export type Data = { date: Date; close: number }[];

type Band = { date: Date; mean: number; lower: number; upper: number };

/** Seeded LCG walk, not Math.random, so the series survives hot reloads unchanged. */
function priceSeries(count: number): Data {
  let seed = 20240101;
  let close = 120;
  return Array.from({ length: count }, (_, i) => {
    seed = (seed * 1103515245 + 12345) % 2147483648;
    close = Math.max(20, close * (1 + (seed / 2147483648 - 0.5) * 0.05) + 0.09);
    return { date: new Date(2024, 0, 1 + i), close };
  });
}

/** Rolling sums in one pass, as the source notebook does, rather than a window per point. */
function bollinger(prices: Data, periods: number, deviations: number): Band[] {
  const bands: Band[] = [];
  let sum = 0;
  let sumSquares = 0;
  prices.forEach(({ date, close }, i) => {
    sum += close;
    sumSquares += close ** 2;
    if (i >= periods) {
      const dropped = prices[i - periods].close;
      sum -= dropped;
      sumSquares -= dropped ** 2;
    }
    if (i < periods - 1) return; // leading window is incomplete, emit nothing rather than NaN
    const mean = sum / periods;
    const spread = Math.sqrt((sumSquares - sum ** 2 / periods) / (periods - 1)) * deviations;
    bands.push({ date, mean, lower: mean - spread, upper: mean + spread });
  });
  return bands;
}

const DEMO: Data = priceSeries(POINTS);

export default function BollingerBands({ data = DEMO, width }: { data?: Data; width: number }) {
  const height = Math.round(width * 0.5);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  const bands = useMemo(() => bollinger(data, PERIODS, DEVIATIONS), [data]);

  const x = useMemo(
    () =>
      d3
        .scaleTime()
        .domain(d3.extent(data, (d) => d.date) as [Date, Date])
        .range([0, innerWidth]),
    [data, innerWidth]
  );

  const y = useMemo(() => {
    const low = Math.min(d3.min(data, (d) => d.close) ?? 0, d3.min(bands, (d) => d.lower) ?? 0);
    const high = Math.max(d3.max(data, (d) => d.close) ?? 0, d3.max(bands, (d) => d.upper) ?? 0);
    return d3.scaleLinear().domain([low, high]).nice().range([innerHeight, 0]);
  }, [data, bands, innerHeight]);

  const envelope = useMemo(
    () =>
      d3
        .area<Band>()
        .x((d) => x(d.date))
        .y0((d) => y(d.lower))
        .y1((d) => y(d.upper))
        .curve(d3.curveMonotoneX)(bands) ?? '',
    [bands, x, y]
  );

  const mean = useMemo(
    () =>
      d3
        .line<Band>()
        .x((d) => x(d.date))
        .y((d) => y(d.mean))
        .curve(d3.curveMonotoneX)(bands) ?? '',
    [bands, x, y]
  );

  const price = useMemo(
    () =>
      d3
        .line<Data[number]>()
        .x((d) => x(d.date))
        .y((d) => y(d.close))(data) ?? '',
    [data, x, y]
  );

  const xTicks: Tick[] = useMemo(
    () => x.ticks(6).map((v) => ({ value: d3.timeFormat('%b %Y')(v), offset: x(v) })),
    [x]
  );

  const yTicks: Tick[] = useMemo(
    () => y.ticks(5).map((v) => ({ value: d3.format('$.0f')(v), offset: y(v) })),
    [y]
  );

  if (width === 0) return null;

  return (
    <svg viewBox={`0 0 ${width} ${height}`} width="100%" height={height} role="img"
         aria-label={`Daily close with ${PERIODS}-period Bollinger bands at ${DEVIATIONS} standard deviations`}>
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <AxisLeft ticks={yTicks} width={innerWidth} />
        <AxisBottom ticks={xTicks} height={innerHeight} width={innerWidth} />
        <path d={envelope} fill="var(--muted)" fillOpacity={0.18} stroke="none" />
        <path d={mean} fill="none" stroke="var(--muted)" strokeWidth={1.25}
              strokeDasharray="4 3" />
        <path d={price} fill="none" stroke="var(--accent)" strokeWidth={1.5}
              strokeLinejoin="round" strokeLinecap="round" />
      </g>
    </svg>
  );
}
